import datetime
import jsonpickle
import time
from six.moves.queue import Empty, Queue
from threading import Thread
from IQCommon.common import LOGIN_TIMEOUT, PRE_TRADING_UPDATE_TIME
from IQCommon.exception import get_traceback_message
from IQCommon.logger import strategy_log, system_log
from IQCommon.util.semaphore_utils import login_semaphore
from IQCommon.util.trade_info_utils import set_trade_stop_status
from IQEngine.const import AccountType, Frequency
from IQEngine.core.events import EventEnum
from IQEngine.core.events.event import Event
from IQEngine.interface import AbstractEventSource
from IQEngine.utils.trade_schedule import is_future_trade_trigger, is_stock_trade_trigger, AFTER_TRADING_TIME, BEFORE_TRADING_TIME, FUTURE_AM_CLOSE, FUTURE_AM_OPEN, FUTURE_PM_CLOSE, FUTURE_PM_OPEN, FUTURE_PM_OVER, HKS_AFTER_TRADING_TIME, HKS_AM_CLOSE, HKS_AM_OPEN, HKS_PM_CLOSE, HKS_PM_OPEN, HKS_PM_OVER, STOCK_AM_CLOSE, STOCK_AM_OPEN, STOCK_PM_CLOSE, STOCK_PM_OPEN, STOCK_PM_OVER
TIME_SLEEP = 1800
TIME_SLEEP_1M = 60
FPS = 3
TIME_DELTA_PREPARED = datetime.timedelta(minutes=10)
TIME_DELTA_TIME_SLEEP = datetime.timedelta(seconds=TIME_SLEEP)
class RealtimeEventSource(AbstractEventSource):
    __doc__ = '\n    实时行情交易事件源\n    '
    def __init__(self, engine):
        self._engine = engine
        self.event_queue = Queue()
        self.initial_trading_date = datetime.date(2000, 1, 1)
        self.pre_before_trading_date = datetime.date(2000, 1, 1)
        self.before_trading_date = datetime.date(2000, 1, 1)
        self.after_trading_date = datetime.date(2000, 1, 1)
        self.handle_data_date = datetime.date(2000, 1, 1)
        self.settlement_date = datetime.date(2000, 1, 1)
        self.last_date_time = datetime.datetime(2000, 1, 1)
        self.last_pre_trading_update_time = None
        self.day_hande_data_flag = 0
        self.clock_engine_thread = Thread(target=self.clock_worker, daemon=True)
        self._engine.event_bus.append_listener(EventEnum.SYSTEM_EXIT, self._on_system_exit)
        self._engine.event_bus.append_listener(EventEnum.SYSTEM_TERMINATE, self._on_system_exit)
        self.active = True
        self.is_rebuild = self._engine.config.plugins.plugin_system_event_source.get('is_rebuild', '0')
        self.rebuild_time = self._engine.config.plugins.plugin_system_event_source.get('rebuild_time', '0')
        self.first_run_date = datetime.datetime.now().date()
    def is_holiday_today(self):
        today = datetime.date.today()
        return (not self._engine.data_proxy.is_trading_date(today))
    def put_before_trading_start(self):
        dt = datetime.datetime.now()
        self._engine.set_current_stage(EventEnum.BEFORE_TRADING_START)
        self.event_queue.put((dt, EventEnum.BEFORE_TRADING_START))
    def clock_worker(self):
        try:
            try:
                holiday_not_do_before = str(self._engine.config.user.holiday_not_do_before)
            except AttributeError:
                holiday_not_do_before = '0'
                break
            else:
                if (holiday_not_do_before == '0'):
                    self.event_queue.put((dt, EventEnum.BEFORE_TRADING_START))
                self.before_trading_date = now_date
            try:
                broker_persist = jsonpickle.decode(self._engine.persist_provider.get_data('broker'))
                persist_flag = True
            except BaseException:
                time.sleep(1)
                if (i == 59):
                    system_log.error('获取持久化对象异常：%s' % get_traceback_message())
            else:
                if (persist_flag is False):
                    set_trade_stop_status(self._engine.config.strategy.trade_id)
                    system_log.error('获取交易持久化对象超时，系统退出')
                    self.event_queue.put((dt, EventEnum.SYSTEM_EXIT))
                    break
                else:
                    self.before_trading_date = now_date
                    try:
                        pass
                    except AttributeError: server_restart_do_before_type = '0'
                    if (server_restart_do_before_type == '0'):
                        self.put_before_trading_start()
                    elif (broker_persist is not None):
                        on_before_trading_start_time_info = broker_persist.get('on_before_trading_start_time')
                        if (on_before_trading_start_time_info is not None):
                            today_date = now_date.strftime('%Y-%m-%d')
                            if (today_date in on_before_trading_start_time_info):
                                today_info = on_before_trading_start_time_info[today_date]
                                if (len(today_info) == 0):
                                    self.put_before_trading_start()
                            else:
                                self.put_before_trading_start()
            accounts = self._engine.config.strategy.accounts
            stock_schedule = self._engine.config.plugins.plugin_system_event_source.get('stock_schedule')
            future_schedule = self._engine.config.plugins.plugin_system_event_source.get('future_schedule')
            hks_schedule = self._engine.config.plugins.plugin_system_event_source.get('hks_schedule')
            if (stock_schedule is None):
                stock_before_trading = BEFORE_TRADING_TIME
                stock_after_trading = AFTER_TRADING_TIME
                stock_am_open = STOCK_AM_OPEN
                stock_am_close = STOCK_AM_CLOSE
                stock_pm_open = STOCK_PM_OPEN
                stock_pm_close = STOCK_PM_CLOSE
                stock_pm_over = STOCK_PM_OVER
            else:
                stock_before_trading = stock_schedule.get('before_trading_time', BEFORE_TRADING_TIME)
                stock_after_trading = stock_schedule.get('after_trading_time', AFTER_TRADING_TIME)
                stock_am_open = stock_schedule.get('am_open', STOCK_AM_OPEN)
                stock_am_close = stock_schedule.get('am_close', STOCK_AM_CLOSE)
                stock_pm_open = stock_schedule.get('pm_open', STOCK_PM_OPEN)
                stock_pm_close = stock_schedule.get('pm_close', STOCK_PM_CLOSE)
                stock_pm_over = stock_schedule.get('pm_over', STOCK_PM_OVER)
            if (future_schedule is None):
                future_before_trading = BEFORE_TRADING_TIME
                future_after_trading = AFTER_TRADING_TIME
                future_am_open = FUTURE_AM_OPEN
                future_am_close = FUTURE_AM_CLOSE
                future_pm_open = FUTURE_PM_OPEN
                future_pm_close = FUTURE_PM_CLOSE
                future_pm_over = FUTURE_PM_OVER
            else:
                future_before_trading = future_schedule.get('before_trading_time', BEFORE_TRADING_TIME)
                future_after_trading = future_schedule.get('after_trading_time', AFTER_TRADING_TIME)
                future_am_open = future_schedule.get('am_open', FUTURE_AM_OPEN)
                future_am_close = future_schedule.get('am_close', FUTURE_AM_CLOSE)
                future_pm_open = future_schedule.get('pm_open', FUTURE_PM_OPEN)
                future_pm_close = future_schedule.get('pm_close', FUTURE_PM_CLOSE)
                future_pm_over = future_schedule.get('pm_over', FUTURE_PM_OVER)
            if (hks_schedule is None):
                hks_before_trading = BEFORE_TRADING_TIME
                hks_after_trading = HKS_AFTER_TRADING_TIME
                hks_am_open = HKS_AM_OPEN
                hks_am_close = HKS_AM_CLOSE
                hks_pm_open = HKS_PM_OPEN
                hks_pm_close = HKS_PM_CLOSE
                hks_pm_over = HKS_PM_OVER
            else:
                hks_before_trading = hks_schedule.get('before_trading_time', BEFORE_TRADING_TIME)
                hks_after_trading = hks_schedule.get('after_trading_time', AFTER_TRADING_TIME)
                hks_am_open = hks_schedule.get('am_open', HKS_AM_OPEN)
                hks_am_close = hks_schedule.get('am_close', HKS_AM_CLOSE)
                hks_pm_open = hks_schedule.get('pm_open', HKS_PM_OPEN)
                hks_pm_close = hks_schedule.get('pm_close', HKS_PM_CLOSE)
                hks_pm_over = hks_schedule.get('pm_over', HKS_PM_OVER)
            if (AccountType.HKS.value in accounts):
                check_trading_time = is_stock_trade_trigger
                if isinstance(hks_before_trading, str):
                    before_trading = datetime.datetime.strptime(hks_before_trading, '%H%M').time()
                else:
                    before_trading = hks_before_trading
                if isinstance(hks_after_trading, str):
                    after_trading = datetime.datetime.strptime(hks_after_trading, '%H%M').time()
                else:
                    after_trading = hks_after_trading
                if isinstance(hks_am_open, str):
                    am_open = datetime.datetime.strptime(hks_am_open, '%H%M').time()
                else:
                    am_open = hks_am_open
                if isinstance(hks_am_close, str):
                    am_close = datetime.datetime.strptime(hks_am_close, '%H%M').time()
                else:
                    am_close = hks_am_close
                if isinstance(hks_pm_open, str):
                    pm_open = datetime.datetime.strptime(hks_pm_open, '%H%M').time()
                else:
                    pm_open = hks_pm_open
                if isinstance(hks_pm_close, str):
                    pm_close = datetime.datetime.strptime(hks_pm_close, '%H%M').time()
                else:
                    pm_close = hks_pm_close
                if isinstance(hks_pm_over, str):
                    pm_over = datetime.datetime.strptime(hks_pm_over, '%H%M').time()
                else:
                    pm_over = hks_pm_over
            elif (AccountType.FUTURE.value in accounts):
                check_trading_time = is_future_trade_trigger
                if isinstance(future_before_trading, str):
                    before_trading = datetime.datetime.strptime(future_before_trading, '%H%M').time()
                else:
                    before_trading = future_before_trading
                if isinstance(future_after_trading, str):
                    after_trading = datetime.datetime.strptime(future_after_trading, '%H%M').time()
                else:
                    after_trading = future_after_trading
                if isinstance(future_am_open, str):
                    am_open = datetime.datetime.strptime(future_am_open, '%H%M').time()
                else:
                    am_open = future_am_open
                if isinstance(future_am_close, str):
                    am_close = datetime.datetime.strptime(future_am_close, '%H%M').time()
                else:
                    am_close = future_am_close
                if isinstance(future_pm_open, str):
                    pm_open = datetime.datetime.strptime(future_pm_open, '%H%M').time()
                else:
                    pm_open = future_pm_open
                if isinstance(future_pm_close, str):
                    pm_close = datetime.datetime.strptime(future_pm_close, '%H%M').time()
                else:
                    pm_close = future_pm_close
                if isinstance(future_pm_over, str):
                    pm_over = datetime.datetime.strptime(future_pm_over, '%H%M').time()
                else:
                    pm_over = future_pm_over
            else:
                check_trading_time = is_stock_trade_trigger
                if isinstance(stock_before_trading, str):
                    before_trading = datetime.datetime.strptime(stock_before_trading, '%H%M').time()
                else:
                    before_trading = stock_before_trading
                if isinstance(stock_after_trading, str):
                    after_trading = datetime.datetime.strptime(stock_after_trading, '%H%M').time()
                else:
                    after_trading = stock_after_trading
                if isinstance(stock_am_open, str):
                    am_open = datetime.datetime.strptime(stock_am_open, '%H%M').time()
                else:
                    am_open = stock_am_open
                if isinstance(stock_am_close, str):
                    am_close = datetime.datetime.strptime(stock_am_close, '%H%M').time()
                else:
                    am_close = stock_am_close
                if isinstance(stock_pm_open, str):
                    pm_open = datetime.datetime.strptime(stock_pm_open, '%H%M').time()
                else:
                    pm_open = stock_pm_open
                if isinstance(stock_pm_close, str):
                    pm_close = datetime.datetime.strptime(stock_pm_close, '%H%M').time()
                else:
                    pm_close = stock_pm_close
                if isinstance(stock_pm_over, str):
                    pm_over = datetime.datetime.strptime(stock_pm_over, '%H%M').time()
                else:
                    pm_over = stock_pm_over
            now_date = datetime.date.today()
            pre_before_trading = (datetime.datetime.combine(now_date, before_trading) + datetime.timedelta(minutes=-1)).time()
            if (self._engine.config.strategy.frequency == Frequency.MINUTE.value):
                def check_handle_date(now_date_):
                    return True
            else:
                def check_handle_date(now_date_):
                    return (now_date_ > self.handle_data_date)
            delay_delta = datetime.timedelta(minutes=5)
            delay_after_trading = (datetime.datetime.combine(now_date, after_trading) + delay_delta).time()
            pre_trading_update_time_str = PRE_TRADING_UPDATE_TIME
            if isinstance(pre_trading_update_time_str, str):
                pre_trading_update_time = datetime.datetime.strptime(pre_trading_update_time_str, '%H%M').time()
            else:
                pre_trading_update_time = pre_trading_update_time_str
            while True:
                while self.active:
                    dt = datetime.datetime.now()
                    while dt.replace(second=0, microsecond=0) <= self.last_date_time:
                        time.sleep(0.5)
                        dt = datetime.datetime.now()
                    self.last_date_time = dt
                    now_date = dt.date()
                    now_time = dt.time()
                    current_minute_key = (now_date, now_time.hour, now_time.minute)
                    if (now_time.hour == pre_trading_update_time.hour):
                        pass
                    if (now_time.minute == pre_trading_update_time.minute and current_minute_key != self.last_pre_trading_update_time):
                        self.event_queue.put((dt, EventEnum.PRE_TRADING_UPDATE))
                        self.last_pre_trading_update_time = current_minute_key
                        system_log.info('触发盘前更新事件，时间：{}'.format(dt))
                    if self.is_holiday_today():
                        if (now_date > self.pre_before_trading_date):
                            if (pre_before_trading <= now_time < pm_close or Exception):
                                self.event_queue.put((dt, EventEnum.PRE_BEFORE_TRADING_START))
                                self.pre_before_trading_date = now_date
                        elif (self.pre_before_trading_date == self.initial_trading_date):
                            pass
                    elif (self.is_rebuild == '1' and now_date > self.first_run_date):
                        current_time = str(now_time).split('.')[0].replace(':', '')[:4]
                        if (current_time >= self.rebuild_time):
                            strategy_log.warning('开始重启交易进程')
                            self.event_queue.put((dt, EventEnum.SYSTEM_REBUILD))
                    if (now_date > self.before_trading_date):
                        if (not before_trading <= now_time < pm_close):
                            pass
                    elif (self.before_trading_date == self.initial_trading_date):
                        pass
                    break
                    if (now_date > self.pre_before_trading_date and (pre_before_trading <= now_time < pm_close or Exception)):
                        system_log.debug('获取重登信号量')
                        if (now_date != self.first_run_date and login_semaphore.acquire(timeout=LOGIN_TIMEOUT * 60) is False):
                            system_log.error('获取重登信号量超时，系统退出')
                            self.event_queue.put((dt, EventEnum.SYSTEM_EXIT))
                            break
                        else:
                            self.event_queue.put((dt, EventEnum.PRE_BEFORE_TRADING_START))
                            self.pre_before_trading_date = now_date
                            if (now_date > self.before_trading_date):
                                if (before_trading <= now_time < pm_close or self.before_trading_date == self.initial_trading_date):
                                    broker_persist = None
                                    persist_flag = False
                                    for i in range(60):
                                        system_log.error('获取持久化对象异常：%s' % get_traceback_message())
                                elif check_trading_time(am_open, am_close, pm_open, pm_close, pm_over, self._engine.config.strategy.frequency, now_time):
                                    if check_handle_date(now_date):
                                        self._engine.set_current_stage(EventEnum.HANDLE_DATA)
                                        self.event_queue.put((dt, EventEnum.HANDLE_DATA))
                                        self.handle_data_date = now_date
                                    else:
                                        time.sleep(TIME_SLEEP_1M)
                                elif (now_date == self.before_trading_date and now_date > self.after_trading_date):
                                    if (delay_after_trading >= now_time >= after_trading):
                                        self._engine.set_current_stage(EventEnum.AFTER_TRADING_END)
                                        self.event_queue.put((dt, EventEnum.AFTER_TRADING_END))
                                        self.after_trading_date = now_date
                                    else:
                                        time.sleep(FPS)
                                set_trade_stop_status(self._engine.config.strategy.trade_id)
                                system_log.error('获取交易持久化对象超时，系统退出')
                                self.event_queue.put((dt, EventEnum.SYSTEM_EXIT))
                                break
                    if (self.pre_before_trading_date == self.initial_trading_date):
                        pass
                    server_restart_do_before_type = '0'
                self.event_queue.put((dt, EventEnum.BEFORE_TRADING_START))
                self.before_trading_date = now_date
                break
        except Exception as ex:
            system_log.error(get_traceback_message())
            return None
    def get_one_event(self):
        while True:
            try:
                return self.event_queue.get(timeout=1)
            except Empty: pass
    def events(self, start_date, end_date, frequency):
        self.clock_engine_thread.start()
        (dt, event_type) = self.get_one_event()
        while True:
            while event_type:
                if (event_type == EventEnum.HANDLE_DATA):
                    now_dt = datetime.datetime.now().strftime('%Y%m%d%H%M%S')
                    if (dt.strftime('%Y%m%d%H%M%S') == now_dt):
                        system_log.debug('event_type {}, real_dt {}, dt {}'.format(event_type, dt, dt))
                        if self.active:
                            yield Event(event_type, calendar_dt=dt, trading_dt=dt)
                    elif (dt.strftime('%Y%m%d%H%M%S') > now_dt):
                        continue
                    else:
                        system_log.debug('当前事件触发时间小于系统时间，无法触发，获取下一个事件')
                        system_log.debug('event_type {}, real_dt {}, dt {}'.format(event_type, dt, dt))
                else:
                    system_log.debug('event_type {}, real_dt {}, dt {}'.format(event_type, dt, dt))
                    if self.active:
                        yield Event(event_type, calendar_dt=dt, trading_dt=dt)
                dt = self.get_one_event()
            break
    def _on_system_exit(self, event):
        self.event_queue.put((None, None))
    def stop(self):
        self.active = False
        self.clock_engine_thread.join()
    def restart(self):
        self.active = True
        self.event_queue = Queue()
        self.initial_trading_date = datetime.date(2000, 1, 1)
        self.pre_before_trading_date = datetime.date(2000, 1, 1)
        self.before_trading_date = datetime.date(2000, 1, 1)
        self.after_trading_date = datetime.date(2000, 1, 1)
        self.handle_data_date = datetime.date(2000, 1, 1)
        self.settlement_date = datetime.date(2000, 1, 1)
        self.last_date_time = datetime.datetime(2000, 1, 1)
        self.last_pre_trading_update_time = None
        self.day_hande_data_flag = 0
        self.clock_engine_thread = Thread(target=self.clock_worker, daemon=True)
        self.clock_engine_thread.start()
